class Commando < Formula
  desc "Colorful TUI that turns a command's man page into a form for its options"
  homepage "https://github.com/lonedevel/commando"
  license "Apache-2.0"

  head do
    url "https://github.com/lonedevel/commando.git", branch: "main"
    depends_on "go" => :build
  end

  # Generated by scripts/update-formula.sh from the release's checksums.txt.
  on_macos do
    on_arm do
      url "https://github.com/lonedevel/commando/releases/download/v0.15.0/commando_0.15.0_darwin_arm64.tar.gz"
      sha256 "bc1f48a7d8534e152503b2e716a410f7e7e585fc5aebfa192d00f1839053e4c8"
    end
    on_intel do
      url "https://github.com/lonedevel/commando/releases/download/v0.15.0/commando_0.15.0_darwin_amd64.tar.gz"
      sha256 "e408955d99fae39c70dce0cb0dcf7b976f035b66a6737a2b4e61ab09a8cda96f"
    end
  end

  on_linux do
    on_arm do
      url "https://github.com/lonedevel/commando/releases/download/v0.15.0/commando_0.15.0_linux_arm64.tar.gz"
      sha256 "c9fecebc084393f9696647837db5d4094325e9fec58192ebd532cbfb3ba60d52"
    end
    on_intel do
      url "https://github.com/lonedevel/commando/releases/download/v0.15.0/commando_0.15.0_linux_amd64.tar.gz"
      sha256 "4040a7144b79e5d1590bb2c460fad3ef27b0d58580da5c76e7ba667f729b539e"
    end
  end

  def install
    if build.head?
      system "go", "build", *std_go_args(ldflags: "-s -w -X main.version=#{version}"), "./cmd/commando"
    else
      bin.install "commando"
    end
  end

  def caveats
    <<~EOS
      To edit the command you're typing with Ctrl-X Ctrl-O, add to your shell config:
        zsh:  eval "$(commando --init zsh)"
        bash: eval "$(commando --init bash)"
        fish: commando --init fish | source
    EOS
  end

  test do
    assert_match version.to_s, shell_output("#{bin}/commando --version")
    assert_match "bindkey", shell_output("#{bin}/commando --init zsh")

    # Parse a manual without needing a terminal.
    ENV["COMMANDO_CACHE_DIR"] = testpath/"cache"
    output = shell_output("#{bin}/commando --dump --no-cache ls")
    assert_match "\"names\"", output
  end
end
